"""Version compatibility and callback-free pre-state container projections."""
import ast

import pytest
from hypothesis import given, settings, strategies as st

from tharkun.solve import terms as t
from tharkun.solve.predicates import check_predicate


BUILTINS = {"type", "len", "int", "bool", "float", "str", "bytes", "list", "tuple", "dict"}

# Fixed v1 text, rather than text generated by the new serializer.
V1_CORPUS = [
    '(term 1 (var Py "x"))', '(term 1 (var Int "i"))',
    '(term 1 (lit Int -7))', '(term 1 (lit Bool true))',
    '(term 1 (lit F64 "-0x0.0p+0"))', '(term 1 (lit F64 "nan"))',
    '(term 1 (tag Tag "NoneType"))',
    '(term 1 (typeis Bool (var Py "x") (tag Tag "int")))',
    '(term 1 (as_int Int (var Py "x")))',
    '(term 1 (as_bool Bool (var Py "x")))',
    '(term 1 (as_f64 F64 (var Py "x")))',
    '(term 1 (b2i Int (lit Bool true)))', '(term 1 (i2f F64 (lit Int -7)))',
    '(term 1 (and Bool (lit Bool true) (lit Bool false)))',
    '(term 1 (or Bool (lit Bool false) (lit Bool true)))',
    '(term 1 (not Bool (lit Bool false)))', '(term 1 (neg Int (lit Int -7)))',
] + [f'(term 1 ({op} {sort} (lit Int -7) (lit Int 3)))'
     for op, sort in [(op, "Bool") for op in ("eq", "ne", "lt", "le", "gt", "ge")]
     + [(op, "Int") for op in ("add", "sub", "mul", "floordiv", "mod")]]


@pytest.mark.parametrize("text", V1_CORPUS)
def test_m5_preserves_every_v1_corpus_byte(text):
    decoded = t.from_canon(text)
    assert isinstance(decoded, t.Term)
    assert t.canon(decoded) == text


def view(kind, domain=None, name="xs"):
    value = t.var(name)
    return (t.as_map(value, primitive_domain=domain) if kind == "dict"
            else t.as_seq(value, kind, primitive_domain=domain))


def primitive(value):
    return t.key_literal(value) if type(value) in (str, bytes) else t.literal(value)


def guarded(kind, condition, name="xs"):
    return t.and_(t.typeis(t.var(name), kind), condition)


@pytest.mark.parametrize("kind", ["list", "tuple", "dict"])
def test_container_terms_use_v2_and_keep_one_py_binding(kind):
    value = view(kind, "int")
    terms = [value, t.length(value), t.contains(value, t.literal(True)),
             guarded(kind, t.gt(t.length(value), t.literal(0)))]
    for term in terms:
        text = t.canon(term)
        assert text.startswith("(term 2 ")
        assert t.from_canon(text) == term
        assert t.canon(t.from_canon(text)) == text
        assert t._variables(term) == {"xs": t.PY}
        renamed = t.rename(term, {"xs": "after_xs"})
        assert t.canon(renamed) == text.replace('"xs"', '"after_xs"')


@pytest.mark.parametrize("term", [t.key_literal("\ud800K\x00"), t.key_literal(b"\x00\xff"),
    t.length(t.key_literal("😀e\u0301")), t.length(t.key_literal(b"\xff\x00"))])
def test_key_literal_encoding_and_length_roundtrip(term):
    text = t.canon(term)
    assert text.startswith("(term 2 ")
    assert t.from_canon(text) == term
    assert t.canon(t.from_canon(text)) == text


@pytest.mark.parametrize("text,version", [
    ('(term 1 (len Int (key Py "str" "x")))', "1"),
    ('(term 2 (lit Int 1))', "2"),
    ('(term 99 (lit Int 1))', "99"),
    ('(term 2 (key Py "bytes" "FF"))', "2"),
    ('(term 2 (getitem Py (var Py "xs") (lit Int 0)))', "2"),
])
def test_version_specific_refusals_identify_version(text, version):
    result = t.from_canon(text)
    assert isinstance(result, t.Refused)
    assert version in result.reason


@pytest.mark.parametrize("make", [
    lambda: t.as_seq(t.var("xs"), "set"),
    lambda: t.as_map(t.var("xs"), primitive_domain="float"),
    lambda: t.as_seq(t.var("xs"), primitive_domain="object"),
    lambda: t.as_seq(t.var("xs"), primitive_domain="int|bool"),
    lambda: t.as_map(t.literal(1)), lambda: t.key_literal(1),
    lambda: t.contains(view("list", "int"), t.literal(float("nan"))),
    lambda: t.as_int(t.key_literal("x")), lambda: t.as_bool(t.key_literal(b"x")),
    lambda: t.as_f64(t.key_literal("x")),
])
def test_unsupported_container_construction_refuses(make):
    assert isinstance(make(), t.Refused)


@pytest.mark.parametrize("sort", [t.SEQ, t.MAP])
def test_direct_container_variables_are_not_second_source_aliases(sort):
    term = t.var("xs", sort)
    assert isinstance(t.eval_term(term, {"xs": []}), t.Refused)
    assert isinstance(t.from_canon(t.canon(term)), t.Refused)
    assert isinstance(t.to_python(t.eq(t.length(term), t.literal(0))), t.Refused)


@pytest.mark.parametrize("kind", ["list", "tuple", "dict"])
@pytest.mark.parametrize("domain,items,needles", [
    ("int", [0, 1, -7, 1 << 200], [True, False, 1, -7, 2, "1", b"1"]),
    ("bool", [False, True], [0, 1, 2, True, False, "True"]),
    ("str", ["", "K", "\ud800", "😀"], ["K", "K", "\ud800", b"", 0]),
    ("bytes", [b"", b"\x00\xff"], [b"", b"\x00\xff", "", False]),
])
def test_native_and_rendered_membership_match_cpython(kind, domain, items, needles):
    actual = dict.fromkeys(items, object()) if kind == "dict" else (tuple(items) if kind == "tuple" else items)
    types = {"xs": f"{kind}[{domain}]"}
    for needle in needles:
        term = guarded(kind, t.contains(view(kind, domain), primitive(needle)))
        text = t.to_python(term, types=types, builtin_names=BUILTINS)
        assert isinstance(text, str)
        check_predicate(text, types, builtin_names=BUILTINS)
        expected = needle in actual
        assert t.eval_term(term, {"xs": actual}) is expected
        assert eval(text, {}, {"xs": actual}) is expected


@pytest.mark.parametrize("kind", ["list", "tuple", "dict"])
@settings(max_examples=40, deadline=None)
@given(st.lists(st.integers(), max_size=12), st.integers())
def test_signed_unbounded_integer_container_native_render_roundtrip(kind, items, needle):
    actual = dict.fromkeys(items) if kind == "dict" else (tuple(items) if kind == "tuple" else items)
    term = guarded(kind, t.contains(view(kind, "int"), t.literal(needle)))
    text = t.to_python(term, types={"xs": f"{kind}[int]"}, builtin_names=BUILTINS)
    assert isinstance(text, str)
    assert t.eval_term(term, {"xs": actual}) is (needle in actual)
    assert eval(text, {}, {"xs": actual}) is (needle in actual)
    assert t.from_canon(t.canon(term)) == term


@pytest.mark.parametrize("actual,kind", [([], "list"), ((1, 1), "tuple"),
    ({1: object(), True: object()}, "dict"), ([object()], "list"),
    ({object(): object()}, "dict")])
def test_length_needs_no_primitive_domain_and_never_inspects_contents(actual, kind):
    term = guarded(kind, t.eq(t.length(view(kind)), t.literal(len(actual))))
    text = t.to_python(term, builtin_names=BUILTINS)
    assert isinstance(text, str)
    assert t.eval_term(term, {"xs": actual}) is True
    assert eval(text, {}, {"xs": actual}) is True


@pytest.mark.parametrize("actual", ["", "😀e\u0301\ud800", b"", b"\x00\xff"])
def test_string_bytes_length_counts_python_units_not_encoded_characters(actual):
    term = t.eq(t.length(t.key_literal(actual)), t.literal(len(actual)))
    text = t.to_python(term, builtin_names={"len"})
    assert isinstance(text, str)
    assert t.eval_term(term, {}) is eval(text) is True
    name = t.var("s")
    term = t.and_(t.typeis(name, type(actual).__name__), t.eq(t.length(name), t.literal(len(actual))))
    text = t.to_python(term, builtin_names=BUILTINS)
    assert isinstance(text, str)
    assert t.eval_term(term, {"s": actual}) is eval(text, {}, {"s": actual}) is True


def test_native_views_use_current_prestate_not_cached_length_or_membership():
    xs = [1]
    length = t.length(view("list"))
    member = t.contains(view("list", "int"), t.literal(2))
    assert t.eval_term(length, {"xs": xs}) == 1
    assert t.eval_term(member, {"xs": xs}) is False
    xs.append(2)
    assert t.eval_term(length, {"xs": xs}) == 2
    assert t.eval_term(member, {"xs": xs}) is True


@settings(max_examples=40, deadline=None)
@given(st.one_of(st.text(max_size=30), st.binary(max_size=30)))
def test_v2_primitive_key_and_length_constructor_native_render_roundtrip(value):
    literal = t.key_literal(value)
    assert t.from_canon(t.canon(literal)) == literal
    term = t.eq(t.length(literal), t.literal(len(value)))
    text = t.to_python(term, builtin_names={"len"})
    assert isinstance(text, str)
    assert t.eval_term(term, {}) is eval(text) is True
    assert t.from_canon(t.canon(term)) == term


def test_membership_refuses_unverified_or_wrong_heap_domains():
    term = guarded("list", t.contains(view("list", "int"), t.literal(1)))
    for types in (None, {}, {"xs": "list"}, {"xs": "list[bool]"}, {"xs": "dict[int]"}):
        assert isinstance(t.to_python(term, types=types, builtin_names=BUILTINS), t.Refused)
    no_domain = guarded("list", t.contains(view("list"), t.literal(1)))
    assert isinstance(t.to_python(no_domain, types={"xs": "list[int]"}, builtin_names=BUILTINS), t.Refused)
    assert isinstance(t.eval_term(no_domain, {"xs": [1]}), t.Refused)
    # Claimed contents are checked independently during native evaluation.
    for actual in ([True], [1.0], [None], [1, True]):
        assert isinstance(t.eval_term(term, {"xs": actual}), t.Refused)


def test_container_evaluation_refuses_protocols_without_calling_them():
    class Meta(type):
        def __eq__(cls, other): raise AssertionError("metaclass equality")
        def __hash__(cls): raise AssertionError("metaclass hashing")

    class Poison(metaclass=Meta):
        def __len__(self): raise AssertionError("length")
        def __iter__(self): raise AssertionError("iteration")
        def __eq__(self, other): raise AssertionError("equality")
        def __bool__(self): raise AssertionError("truth")

    class ListSubclass(list):
        def __iter__(self): raise AssertionError("subclass iterator")

    bad = Poison()
    for term, actual in [(t.length(t.var("xs")), bad),
                         (t.length(view("list")), ListSubclass([1])),
                         (t.contains(view("list", "int"), t.literal(1)), [bad]),
                         (t.contains(view("list", "int"), t.var("key")), [1])]:
        assert isinstance(t.eval_term(term, {"xs": actual, "key": bad}), t.Refused)
    assert isinstance(t.key_literal(bad), t.Refused)
    nan = float("nan")
    assert isinstance(t.eval_term(t.contains(view("dict", "int"), t.literal(1)), {"xs": {nan: 1}}), t.Refused)
    # An ignored dict value may have every unsafe protocol.
    assert t.eval_term(t.contains(view("dict", "int"), t.literal(True)), {"xs": {1: bad}}) is True


@pytest.mark.parametrize("form", [lambda g, p: p, lambda g, p: t.and_(p, g),
    lambda g, p: t.or_(g, p), lambda g, p: t.and_(t.not_(g), p),
    lambda g, p: t.or_(t.and_(g, t.literal(False)), p),
    lambda g, p: t.and_(t.typeis(t.var("other"), "list"), p)])
def test_length_and_membership_need_dominating_guard_not_type_hint(form):
    g = t.typeis(t.var("xs"), "list")
    for p in (t.gt(t.length(view("list")), t.literal(0)),
              t.contains(view("list", "int"), t.literal(1))):
        assert isinstance(t.to_python(form(g, p), types={"xs": "list[int]"}, builtin_names=BUILTINS), t.Refused)


def test_len_and_tag_builtin_names_must_be_authenticated_and_unshadowed():
    term = guarded("list", t.ge(t.length(view("list")), t.literal(0)))
    for names in ({"type", "list"}, {"type", "len"}, {"len", "list"}, set()):
        assert isinstance(t.to_python(term, builtin_names=names), t.Refused)
    for name in ("len", "list", "type"):
        assert isinstance(t.to_python(term, types={name: "object"}, builtin_names=BUILTINS), t.Refused)


@pytest.mark.parametrize("source,types,actual", [
    ("type(xs) is list and len(xs) >= 0", {"xs": "object"}, [object()]),
    ("type(xs) is tuple and 1 not in xs", {"xs": "tuple[int]"}, (2, 3)),
    ("type(xs) is dict and True in xs", {"xs": "dict[int]"}, {1: object()}),
    ("type(xs) is list and 'x' in xs", {"xs": "list[str]"}, ["x"]),
    ("type(xs) is tuple and b'\\xff' in xs", {"xs": "tuple[bytes]"}, (b"\xff",)),
    ("type(xs) is str and len(xs) > 0", {"xs": "object"}, "😀"),
])
def test_from_ast_container_projection_matches_source(source, types, actual):
    term = t.from_ast(source, types, builtin_names=BUILTINS)
    assert isinstance(term, t.Term)
    assert t._variables(term) == {"xs": t.PY}
    text = t.to_python(term, types=types, builtin_names=BUILTINS)
    assert isinstance(text, str)
    assert t.eval_term(term, {"xs": actual}) is eval(source, {}, {"xs": actual})
    assert eval(text, {}, {"xs": actual}) is eval(source, {}, {"xs": actual})


@pytest.mark.parametrize("domain,key_kind,items,key", [("int", "bool", [1], True),
    ("bool", "int", [True], 1), ("str", "str", ["x"], "x"),
    ("bytes", "bytes", [b"x"], b"x")])
def test_from_ast_variable_membership_keys_need_their_own_type_guard(domain, key_kind, items, key):
    source = f"type(xs) is list and type(k) is {key_kind} and k in xs"
    types = {"xs": f"list[{domain}]", "k": "object"}
    term = t.from_ast(source, types, builtin_names=BUILTINS)
    text = t.to_python(term, types=types, builtin_names=BUILTINS)
    assert isinstance(text, str)
    for value in (key, object()):
        env = {"xs": items, "k": value}
        assert t.eval_term(term, env) is eval(text, {}, env) is eval(source, {}, env)


@pytest.mark.parametrize("source,types", [
    ("xs[0]", {"xs": "list[int]"}), ("xs[1:]", {"xs": "list[int]"}),
    ("xs.append(1)", {"xs": "list[int]"}), ("len(xs, 1)", {"xs": "list"}),
    ("len(x=xs)", {"xs": "list"}), ("len(*xs)", {"xs": "list"}),
    ("len(xs)", {"xs": "list", "len": "object"}),
    ("1 in xs", {"xs": "list[float]"}), ("1.0 in xs", {"xs": "list[int]"}),
    ("'x' in xs", {"xs": "str"}), ("b'x' in xs", {"xs": "bytes"}),
    ("1 in [1]", {}), ("False and xs.attr", {"xs": "list[int]"}),
])
def test_from_ast_keeps_excluded_container_syntax_refused(source, types):
    assert isinstance(t.from_ast(source, types, builtin_names=BUILTINS), t.Refused)


def test_from_ast_malformed_len_and_compare_are_total_or_refused():
    for node in (ast.Call(), ast.Call(func=ast.Name(id="len", ctx=ast.Load()), args=[], keywords=[]),
                 ast.Compare(left=ast.Name(id="xs", ctx=ast.Load()), ops=[ast.In()], comparators=[])):
        assert isinstance(t.from_ast(node, {"xs": "list[int]"}, builtin_names=BUILTINS), t.Refused)
